local NewViewBaseLayer = require("hall.NewViewBaseLayer")
local SelfScoreRecord = class("SelfScoreRecord", NewViewBaseLayer)
local EVENTNAME = {
	SELECT_CLU_HISTORY = "/selectCluHistory",
}

function SelfScoreRecord:ctor(family_id)
    self.family_id = family_id
    local csbPath = "hall/res/FriendScircle/SelfScoreRecord.csb"
    SelfScoreRecord.super.ctor(self, csbPath)
    self:enableMask(true)
    self:initEvent()
    --add by zzy
    self.AllHeHuoRenList = {}
	self.allPartnerList = {}
    self.curPage = 1
	self.page_num = 6
    self.tatolPage = 1
    self.item:hide()
    self:createTableView()
    self:InitGame()
end
function SelfScoreRecord:initEvent()
	
    ReqMgr:addHandle("SelfScoreRecord", EVENTNAME)
    self.r_page:onClick(handler(self, self.btn_r_page))
	self.l_page:onClick(handler(self, self.btn_l_page))
end

function SelfScoreRecord:onExit()
    ReqMgr:delHandle("SelfScoreRecord", EVENTNAME)
end
--test
function SelfScoreRecord:createTableView()
    local ListView = self.ListView
    local size = ListView:getContentSize()
    local pos = ListView:getPosition()
    local anchor = ListView:getAnchorPoint()
    self.userList = cc.TableView:create(size)
    self.userList:setDirection(cc.SCROLLVIEW_DIRECTION_VERTICAL)
    self.userList:setVerticalFillOrder(cc.TABLEVIEW_FILL_TOPDOWN)
    self.userList:setAnchorPoint(anchor)
    self.userList:setPosition(pos)
    self.userList:setDelegate()
    self.userList:addTo(self.root,99)
    self.userList:registerScriptHandler(handler(self, self.tableCellAtIndex), cc.TABLECELL_SIZE_AT_INDEX)
    self.userList:registerScriptHandler(handler(self, self.tableCellTouched), cc.TABLECELL_TOUCHED)
    self.userList:registerScriptHandler(handler(self, self.cellSizeForTable), cc.TABLECELL_SIZE_FOR_INDEX)
    self.userList:registerScriptHandler(handler(self, self.numberOfCellsInTableView), cc.NUMBER_OF_CELLS_IN_TABLEVIEW)
    self.userList:reloadData()
end

--test
function SelfScoreRecord:tableCellAtIndex(view, idx)
    local cell = view:dequeueCell()
    
    local item = nil
    if nil == cell then
        cell = cc.TableViewCell:new()
        local userBar = self:createUser(self.AllHeHuoRenList[idx+1], idx + 1)
        cell:addChild(userBar)
        userBar:setPosition(cc.p(0,0))
    else
        local node = cell:getChildByName("item")
        self:initCellInfo(node,self.AllHeHuoRenList[idx+1], idx + 1)
    end
    return cell
end

function SelfScoreRecord:initCellInfo(_node, userItem, index)
    local coins = userItem.coins or ""
    
    local nickName = require("hall.GameCommon"):formatNick(userItem.nickName or "")
    local opeNickName = require("hall.GameCommon"):formatNick(userItem.opeNickName or "")

    local ownerId = userItem.ownerId
    local playerId = userItem.playerId

    nickName = nickName .. " ("..playerId..")"
    opeNickName = opeNickName .. " (" .. ownerId .. ")"
    local createTime = os.date("%Y-%m-%d %H:%M:%S", userItem.createTime/1000)
    local type = tonumber(userItem.type)
    local useType = tonumber(userItem.useType)
    local descNode = _node.desc
    if type == 0 then
        --type = "-"
        if ownerId == USER_INFO['uid'] then
            descNode:setTextColor(cc.c3b(255, 0, 0))
        end
        if playerId == USER_INFO['uid'] then
            descNode:setTextColor(cc.c3b(0, 128, 0))
        end
    else
        --type = "+"
        if ownerId == USER_INFO['uid'] then
            descNode:setTextColor(cc.c3b(0, 128, 0))
        end
        if playerId == USER_INFO['uid'] then
            descNode:setTextColor(cc.c3b(255, 0, 0))
        end
    end
    _node.desc:setString(nickName)
    --_node.score:setString(type..coins/100)
    _node.time:setString(createTime)

    if useType == 1  then
        _node.txt_handType:setString('上下分')
        if ownerId == USER_INFO['uid'] then
            if type == 0 then
                _node.txt_handType:setString('下分')
                _node.score:setString('+' .. coins/100)
            else
                _node.txt_handType:setString('上分')
                _node.score:setString('-' .. coins/100)
            end
            _node.desc:setString(nickName)
        end
        if playerId == USER_INFO['uid'] then
            if type == 0 then
                _node.txt_handType:setString('被下分')
                _node.score:setString('-' .. coins/100)
            else
                _node.txt_handType:setString('被上分')
                _node.score:setString('+' .. coins/100)
            end
            _node.desc:setString(opeNickName)
        end
    else
        _node.txt_handType:setString('赠送')
        if ownerId == USER_INFO['uid'] then
            _node.txt_handType:setString('赠送')
            _node.score:setString('-' .. coins/100)
            _node.desc:setString(nickName)
        end
        if playerId == USER_INFO['uid'] then
            _node.txt_handType:setString('被赠送')
            _node.score:setString('+' .. coins/100)
            _node.desc:setString(opeNickName)
        end
    end

end

--test
function SelfScoreRecord:createUser(userItem, index)
    local item = self.item:clone()
    item:show()
    item:setName("item")
    GameUtils.setNodeNameBindObj(item)
    self:initCellInfo(item, userItem, index)
    return item
end

function SelfScoreRecord:tableCellTouched(view, cell)
    dump(cell:getIdx())
end

function SelfScoreRecord:cellSizeForTable()
    local itemSize = self.item:getContentSize()
    return itemSize.width, itemSize.height
end

function SelfScoreRecord:numberOfCellsInTableView()
    if not (self and self.AllHeHuoRenList) then return end
    return #self.AllHeHuoRenList or 0
end


function SelfScoreRecord:InitGame(page)
	page = page or 1
    local data = {groupId = self.family_id, playerId = USER_INFO.uid, pageSize = self.page_num, currentPage = page}
    ReqMgr:request(EVENTNAME.SELECT_CLU_HISTORY, data, handler(self , self.FlushPartnerInfo), {page = page})
end

function SelfScoreRecord:FlushPartnerInfo(event)

    local netData = event.netData
	local param = event.param
	local returnCode = netData.returnCode
	local data = netData.data
    local error = netData.error
    if not (returnCode == 0) then
        viewMgr:showTip({text = error})
        return
    end
    dump(data,"FlushPartnerInfo_data")
    self.AllHeHuoRenList = {}
    self.AllHeHuoRenList = data.list
	self.allPartnerList = data
    if #(self.AllHeHuoRenList) >= 1 then
        self.desc:hide()
    else
        self.desc:show()
    end
    self.tatolPage = math.ceil(data.listCount / self.page_num)
	if self.tatolPage == 0 then
        self.tatolPage = 1
    end
	self.curPage = param.page
    self.r_text:setString(self.curPage.."/"..self.tatolPage)
    
    self:FlushPartnerList_new(data)
end

function SelfScoreRecord:FlushPartnerList_new(data)
    if not data.list then return end
    self.userList:reloadData()
end

function SelfScoreRecord:onClickBtnReturn(...)
    self:removeSelf()
end

function SelfScoreRecord:btn_r_page()
	local page = self.curPage + 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page)
end

function SelfScoreRecord:btn_l_page()
	local page = self.curPage - 1
	if page <= 0 or page > self.tatolPage or self.curPage == page then
		return
	end
	self:InitGame(page)
end

return SelfScoreRecord